/**
 * 词汇积累的一张词的详情纸：词、音标、词性在最上面，下面释义、搭配、
 * 例句、用法一栏一栏铺开 —— 卡片上装不下的，都摊在这一页里。
 */
function WordDetailSheet({ word }: { word: VocabularyWord }) {
  return (
    <article className="leafia-word-viewer__sheet">
      <header>
        <h4>{word.term}</h4>
        {/* 发音在音标前面：先听见，再核对怎么读（和单词本词页同一个规矩）。 */}
        <p className="leafia-word-viewer__sound">
          <button
            type="button"
            aria-label={`朗读 ${word.term}`}
            title="朗读单词"
            onClick={() => speakEnglish(word.term)}
          >
            <Volume2 size={14} />
          </button>
          <em>{word.pronunciation ?? word.lemma}</em>
          <span>
            {word.partOfSpeech ?? "expression"} · {word.cefr ?? "B1-B2"}
          </span>
        </p>
      </header>
      {word.meaningsZh.length > 0 ? (
        <section>
          <small>释义</small>
          <p>{word.meaningsZh.join("；")}</p>
        </section>
      ) : null}
      {word.definitionEn ? (
        <section>
          <small>Definition</small>
          <p>{word.definitionEn}</p>
        </section>
      ) : null}
      {word.collocations.length > 0 ? (
        <section>
          <small>搭配</small>
          <div className="leafia-word-viewer__chips">
            {word.collocations.slice(0, 8).map((collocation) => (
              <span key={collocation}>{collocation}</span>
            ))}
          </div>
        </section>
      ) : null}
      {word.examples[0] ? (
        <section>
          <small>例句</small>
          <blockquote>{word.examples[0].text}</blockquote>
          {word.examples[0].translationZh ? (
            <p className="leafia-word-viewer__translation">
              {word.examples[0].translationZh}
            </p>
          ) : null}
        </section>
      ) : null}
      {word.usageNotes.length > 0 ? (
        <section>
          <small>用法</small>
          <ul>
            {word.usageNotes.slice(0, 4).map((note) => (
              <li key={note}>{note}</li>
            ))}
          </ul>
        </section>
      ) : null}
      <footer>
        <small>{word.sourceLabel}</small>
        <span>{word.reviewCount} 轮复习</span>
      </footer>
    </article>
  );
}

function WordDrawer() {
  const initialized = useVocabulary((state) => state.initialized);
  const hydrate = useVocabulary((state) => state.hydrate);
  const words = useVocabulary((state) => state.words);
  const removeWord = useVocabulary((state) => state.removeWord);
  const [viewWordId, setViewWordId] = useState<string | null>(null);
  const [pendingRemoval, setPendingRemoval] = useState<VocabularyWord | null>(
    null,
  );
  const swipeStartRef = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  const viewWord = viewWordId
    ? words.find((word) => word.id === viewWordId)
    : undefined;

  /* 在盘里左右滑（或点 ‹ ›）接着翻下一张词，返回才回卡片盘。 */
  const stepView = (delta: number) => {
    if (!viewWordId) return;
    const index = words.findIndex((word) => word.id === viewWordId);
    if (index < 0) return;
    const next = words[Math.min(words.length - 1, Math.max(0, index + delta))];
    if (next) setViewWordId(next.id);
  };

  /* 抽屉里就摆词：一排卡片沿深度轴退下去，拖动或滚轮翻页，点中间那张
     摊开详细释义（viewWord）。卡面从上到下是：词、音标、词性+释义 ——
     词性跟着意思走，卡顶不再单独占一行。 */
  const items = words.map((word) => ({
    id: word.id,
    word: word.term,
    phonetic: word.pronunciation,
    tag: word.partOfSpeech ?? "expression",
    tagBeforeMeaning: true,
    meaning: word.meaningsZh.join("；") || word.definitionEn,
    rounds: word.reviewCount,
  }));

  return (
    <>
      <section className="leafia-drawer-wordfield">
        <DepthCardRail
          items={items}
          emptyLabel={
            initialized
              ? "单词本还空着。去书里、词典里收几个词，它们会排到这儿来。"
              : "正在翻开单词本……"
          }
          hint="拖动 / 滚轮翻页 · 点中间那张查看详细释义"
          onSelect={(item) => setViewWordId(item.id)}
        />
      </section>

      {/* 点开的那张词：详细释义铺满整个抽屉页面，左右滑／‹ › 在这一盘里
          翻上一张下一张；朗读和删除都收在这一层里。 */}
      {viewWord ? (
        <section
          className="leafia-word-viewer"
          aria-label={`${viewWord.term} 详细释义`}
          onPointerDown={(event) => {
            swipeStartRef.current = { x: event.clientX, y: event.clientY };
          }}
          onPointerUp={(event) => {
            const start = swipeStartRef.current;
            swipeStartRef.current = null;
            if (!start) return;
            const dx = event.clientX - start.x;
            const dy = event.clientY - start.y;
            // 横向为主的一下才算「翻一张」；纵向手势留给详情自己的滚动。
            if (Math.abs(dx) > 56 && Math.abs(dx) > Math.abs(dy)) {
              stepView(dx < 0 ? 1 : -1);
            }
          }}
        >
          <header className="leafia-knowledge-viewer__bar">
            <button
              type="button"
              className="leafia-knowledge-viewer__back"
              aria-label="返回词汇积累"
              onClick={() => setViewWordId(null)}
            >
              <ArrowLeft size={16} />
            </button>
            <span className="leafia-knowledge-viewer__step">
              <button
                type="button"
                aria-label="上一个词"
                onClick={() => stepView(-1)}
              >
                ‹
              </button>
              <button
                type="button"
                aria-label="下一个词"
                onClick={() => stepView(1)}
              >
                ›
              </button>
            </span>
          </header>
          <WordDetailSheet key={viewWord.id} word={viewWord} />
          <footer className="leafia-knowledge-carousel__actions">
            <button
              type="button"
              onClick={() => speakEnglish(viewWord.term)}
            >
              <Volume2 size={14} />
              朗读
            </button>
            <button
              type="button"
              aria-label={`删除 ${viewWord.term}`}
              onClick={() => setPendingRemoval(viewWord)}
            >
              <Trash2 size={13} />
            </button>
          </footer>
          <p className="leafia-knowledge-viewer__hint">左右滑动翻看这一盘词</p>
        </section>
      ) : null}

      <DiscardPaper
        spec={
          pendingRemoval
            ? {
                key: `word:${pendingRemoval.id}`,
                kicker: "Discard · 词汇积累",
                title: pendingRemoval.term,
                meta: pendingRemoval.meaningsZh.join("；"),
                seed: pendingRemoval.term.length * 13 + 5,
              }
            : null
        }
        onCancel={() => setPendingRemoval(null)}
        onConfirm={() => {
          if (pendingRemoval) removeWord(pendingRemoval.id);
          setPendingRemoval(null);
          setViewWordId(null);
        }}
      />
    </>
  );
}

/** 要点和关联词汇两个字段都是「一行一条，逗号也认」。 */
function splitCardLines(value: string) {
  return value
    .split(/\n|,/)
    .map((item) => item.trim())
    .filter(Boolean);
}

/**
 * 知识卡摊开的那张纸（D1）：正面在上、要点和关联词汇在下，中间压一道折线。
 * 自建卡不翻面 —— 写的时候看见的整张，就是收进收藏里的样子。
 */
function KnowledgeCardSheet({
  className = "",
  categoryLabel,
  sourceLabel,
  title,
  summary,
  keyPoints,
  terms,
  placeholder,
}: {
  className?: string;
  categoryLabel: string;
  sourceLabel: string;
  title: string;
  summary: string;
  keyPoints: string[];
  terms: string[];
  placeholder: string;
}) {
  const backEmpty = keyPoints.length === 0 && terms.length === 0;

  return (
    <div className={cn("leafia-card-flip__still", className)}>
      <header>
        <small>
          {categoryLabel} · {sourceLabel}
        </small>
        <h4>{title.trim() || placeholder}</h4>
        {summary.trim() ? <p>{summary}</p> : null}
      </header>
      <span className="leafia-card-flip__fold" aria-hidden="true" />
      <div className="leafia-card-flip__back">
        {keyPoints.length > 0 ? (
          <section>
            <small>要点</small>
            <ul>
              {keyPoints.slice(0, 4).map((point, index) => (
                <li key={`${index}-${point}`}>{point}</li>
              ))}
            </ul>
          </section>
        ) : null}
        {terms.length > 0 ? (
          <section>
            <small>关联词汇</small>
            <div className="leafia-card-flip__terms">
              {terms.slice(0, 10).map((term, index) => (
                <span key={`${index}-${term}`}>{term}</span>
              ))}
            </div>
          </section>
        ) : null}
        {backEmpty ? <p className="leafia-card-flip__blank">这一面还空着。</p> : null}
      </div>
    </div>
  );
}

function KnowledgeDrawer() {
  const hydrate = useKnowledge((state) => state.hydrate);
  const cards = useKnowledge((state) => state.cards);
  const addManualCard = useKnowledge((state) => state.addManualCard);
  const removeCard = useKnowledge((state) => state.removeCard);
  const setCardMastery = useKnowledge((state) => state.setCardMastery);
  const updateCard = useKnowledge((state) => state.updateCard);
  const [query, setQuery] = useState("");
  const [categoryId, setCategoryId] = useState<string>("all");
  const [composerOpen, setComposerOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [summary, setSummary] = useState("");
  const [keyPoints, setKeyPoints] = useState("");
  const [terms, setTerms] = useState("");
  const [newCategory, setNewCategory] =
    useState<KnowledgeCategoryId>("linguistics");
  /** 正等着被揉掉的那张知识卡（E3：删除就是把这页纸揉成一团）。 */
  const [pendingRemoval, setPendingRemoval] = useState<KnowledgeCard | null>(
    null,
  );
  /** 正在「看」的那张卡：点卡片是查看，不是编辑 —— 详情盖在抽屉上，
      左右滑可以接着翻这一系列。 */
  const [viewCardId, setViewCardId] = useState<string | null>(null);
  const swipeStartRef = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  const filtered = cards.filter((card) => {
    if (categoryId !== "all" && card.categoryId !== categoryId) return false;
    const normalized = query.trim().toLowerCase();
    if (!normalized) return true;
    return `${card.title} ${card.summaryZh} ${card.terms.join(" ")}`
      .toLowerCase()
      .includes(normalized);
  });

  /* 卡面就两样：标题，和它下面标注的出处（哪本书，或自建）——
     摘要、掌握状态都收进点开后的详情里，一盘卡先让人一眼看清
     「一共有哪些、分别从哪儿来」。 */
  const carouselItems = filtered.map((card) => {
    const book = card.bookId ? knowledgeBookById(card.bookId) : undefined;
    const source =
      book?.zhTitle ?? (card.source === "manual" ? "自建" : "书本收藏");
    return { id: card.id, word: card.title, tag: source };
  });

  /** 详情里正在看的那张：跟着筛选走，被筛掉就自动回到列表。 */
  const viewCard: KnowledgeCard | null = viewCardId
    ? filtered.find((card) => card.id === viewCardId) ?? null
    : null;

  const cardLabels = (card: KnowledgeCard) => {
    const category = KNOWLEDGE_CATEGORIES.find(
      (item) => item.id === card.categoryId,
    );
    const book = card.bookId ? knowledgeBookById(card.bookId) : undefined;
    return {
      categoryLabel: category?.titleZh ?? card.categoryId,
      sourceLabel: `${book?.zhTitle ?? (card.source === "manual" ? "自建" : "书本收藏")}${
        card.mastery === "mastered" ? " · 已掌握" : ""
      }`,
    };
  };
  const viewLabels = viewCard ? cardLabels(viewCard) : null;

  /** 详情里左右滑 / ‹ ›：在这一系列里上一张下一张。 */
  const stepView = (dir: 1 | -1) => {
    if (!viewCard) return;
    const index = filtered.findIndex((card) => card.id === viewCard.id);
    const next = filtered[index + dir];
    if (!next) return;
    setViewCardId(next.id);
  };

  /** 写入界面那张预览卡跟着正在编辑的这张走：改旧的，类别用旧的，别用新建时的默认值。 */
  const previewCategoryId =
    (editingId ? cards.find((card) => card.id === editingId)?.categoryId : null) ??
    newCategory;

  const resetComposer = () => {
    setEditingId(null);
    setTitle("");
    setSummary("");
    setKeyPoints("");
    setTerms("");
    setComposerOpen(false);
  };

  const save = () => {
    if (!title.trim() || !summary.trim()) return;
    if (editingId) {
      updateCard(editingId, {
        title: title.trim(),
        summaryZh: summary.trim(),
        keyPoints: splitCardLines(keyPoints),
        terms: splitCardLines(terms),
      });
    } else {
      addManualCard({
        categoryId: newCategory,
        title: title.trim(),
        summaryZh: summary.trim(),
        keyPoints: splitCardLines(keyPoints),
        terms: splitCardLines(terms),
      });
    }
    resetComposer();
  };

  const edit = (card: KnowledgeCard) => {
    setEditingId(card.id);
    setTitle(card.title);
    setSummary(card.summaryZh);
    setKeyPoints(card.keyPoints.join("\n"));
    setTerms(card.terms.join(", "));
    setComposerOpen(true);
  };

  return (
    <>
      <div className="leafia-drawer-tools">
        <label>
          <Search size={15} />
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="搜索知识点或词汇…"
          />
        </label>
        <button
          type="button"
          onClick={() => setComposerOpen((value) => !value)}
        >
          <Plus size={15} />
          新建知识卡
        </button>
      </div>

      <div className="leafia-drawer-segments">
        <button
          type="button"
          className={cn(categoryId === "all" && "is-active")}
          onClick={() => setCategoryId("all")}
        >
          全部
        </button>
        {KNOWLEDGE_CATEGORIES.map((category) => (
          <button
            type="button"
            key={category.id}
            className={cn(categoryId === category.id && "is-active")}
            onClick={() => setCategoryId(category.id)}
          >
            {category.titleZh}
          </button>
        ))}
      </div>

      {composerOpen ? (
        <form
          className="leafia-card-composer"
          onSubmit={(event) => {
            event.preventDefault();
            save();
          }}
        >
          <header className="leafia-card-composer__head">
            <span>
              <small>{editingId ? "Editing" : "New card"}</small>
              <strong>{editingId ? "编辑知识卡" : "自建知识卡"}</strong>
            </span>
            {/* 取消是文字，不是又一个 ✕ —— 整扇窗的 ✕ 只留右上角那一个。 */}
            <button
              type="button"
              className="leafia-card-composer__cancel"
              onClick={resetComposer}
            >
              取消
            </button>
          </header>

          <div className="leafia-card-composer__fields">
            {!editingId ? (
              <label className="leafia-card-composer__field">
                <span>类别</span>
                <select
                  value={newCategory}
                  onChange={(event) =>
                    setNewCategory(event.target.value as KnowledgeCategoryId)
                  }
                >
                  {KNOWLEDGE_CATEGORIES.map((category) => (
                    <option key={category.id} value={category.id}>
                      {category.titleZh} · {category.title}
                    </option>
                  ))}
                </select>
              </label>
            ) : null}
            <label className="leafia-card-composer__field">
              <span>标题</span>
              <input
                value={title}
                onChange={(event) => setTitle(event.target.value)}
                placeholder="知识点标题"
              />
            </label>
            <label className="leafia-card-composer__field">
              <span>核心解释</span>
              <textarea
                value={summary}
                onChange={(event) => setSummary(event.target.value)}
                placeholder="一两句话讲清这个知识点"
                rows={4}
              />
            </label>
            <label className="leafia-card-composer__field">
              <span>
                关键要点
                <em>每行一条</em>
              </span>
              <textarea
                value={keyPoints}
                onChange={(event) => setKeyPoints(event.target.value)}
                placeholder="考试里会用到的判断依据…"
                rows={3}
              />
            </label>
            <label className="leafia-card-composer__field">
              <span>
                关联词汇
                <em>逗号分隔</em>
              </span>
              <input
                value={terms}
                onChange={(event) => setTerms(event.target.value)}
                placeholder="phoneme, minimal pair"
              />
            </label>
            <button
              type="submit"
              className="knowledge-primary-button"
              disabled={!title.trim() || !summary.trim()}
            >
              <BookmarkPlus size={15} />
              {editingId ? "保存修改" : "保存知识卡"}
            </button>
          </div>

          {/* 写的时候手边就有这张卡（D1）：右边这一栏跟着左边落笔一起长。 */}
          <KnowledgeCardSheet
            className="leafia-card-composer__preview"
            categoryLabel={
              KNOWLEDGE_CATEGORIES.find((item) => item.id === previewCategoryId)
                ?.titleZh ?? "知识卡"
            }
            sourceLabel={editingId ? "编辑中" : "自建"}
            title={title}
            summary={summary}
            keyPoints={splitCardLines(keyPoints)}
            terms={splitCardLines(terms)}
            placeholder="标题还没写"
          />
        </form>
      ) : null}

      {filtered.length ? (
        /* 收藏摆成一盘白纸卡（DepthCardRail，转盘本体是 React Bits 的
           DepthCarousel）：卡片沿深度轴一层层退下去，一屏里能看见整摞卡的
           去向；拖动或滚轮翻页，点中间那张放大查看（viewCard），
           编辑、掌握、删除都在详情那一层自己的按钮里。 */
        <section className="leafia-knowledge-carousel">
          <DepthCardRail
            items={carouselItems}
            hint="拖动 / 滚轮翻页 · 点中间那张放大查看"
            onSelect={(item) => {
              if (composerOpen) resetComposer();
              setViewCardId(item.id);
            }}
          />
        </section>
      ) : (
        <div className="leafia-drawer-empty">
          <FileText size={20} />
          <strong>还没有知识卡</strong>
          <p>在书本中收藏知识点，或在这里新建一张。</p>
        </div>
      )}

      {/* 点开的那张卡：正反面详细解释铺满整个抽屉页面，左右滑／‹ ›
          在这条收藏里翻上一张下一张；编辑、掌握、删除都收在这一层里。 */}
      {viewCard && viewLabels ? (
        <section
          className="leafia-knowledge-viewer"
          aria-label={`${viewCard.title} 详情`}
          onPointerDown={(event) => {
            swipeStartRef.current = { x: event.clientX, y: event.clientY };
          }}
          onPointerUp={(event) => {
            const start = swipeStartRef.current;
            swipeStartRef.current = null;
            if (!start) return;
            const dx = event.clientX - start.x;
            const dy = event.clientY - start.y;
            // 横向为主的一下才算「翻一张」；纵向手势留给详情自己的滚动。
            if (Math.abs(dx) > 56 && Math.abs(dx) > Math.abs(dy)) {
              stepView(dx < 0 ? 1 : -1);
            }
          }}
        >
          <header className="leafia-knowledge-viewer__bar">
            <button
              type="button"
              className="leafia-knowledge-viewer__back"
              aria-label="返回收藏"
              onClick={() => setViewCardId(null)}
            >
              <ArrowLeft size={16} />
            </button>
            <span className="leafia-knowledge-viewer__step">
              <button
                type="button"
                aria-label="上一张"
                onClick={() => stepView(-1)}
              >
                ‹
              </button>
              <button
                type="button"
                aria-label="下一张"
                onClick={() => stepView(1)}
              >
                ›
              </button>
            </span>
          </header>
          <KnowledgeCardSheet
            key={viewCard.id}
            className="leafia-knowledge-viewer__sheet"
            categoryLabel={viewLabels.categoryLabel}
            sourceLabel={viewLabels.sourceLabel}
            title={viewCard.title}
            summary={viewCard.summaryZh}
            keyPoints={viewCard.keyPoints}
            terms={viewCard.terms}
            placeholder="知识点"
          />
          <footer className="leafia-knowledge-carousel__actions">
            <button
              type="button"
              onClick={() => {
                setViewCardId(null);
                edit(viewCard);
              }}
            >
              编辑
            </button>
            <button
              type="button"
              onClick={() =>
                setCardMastery(
                  viewCard.id,
                  viewCard.mastery === "mastered" ? "learning" : "mastered",
                )
              }
            >
              {viewCard.mastery === "mastered" ? (
                <>
                  <CheckCircle2 size={13} />
                  已掌握
                </>
              ) : (
                "标记掌握"
              )}
            </button>
            <button
              type="button"
              aria-label={`删除 ${viewCard.title}`}
              onClick={() => setPendingRemoval(viewCard)}
            >
              <Trash2 size={13} />
            </button>
          </footer>
          <p className="leafia-knowledge-viewer__hint">左右滑动翻看这一系列</p>
        </section>
      ) : null}

      <DiscardPaper
        spec={
          pendingRemoval
            ? {
                key: `card:${pendingRemoval.id}`,
                kicker: "Discard · 知识收藏",
                title: pendingRemoval.title,
                meta: pendingRemoval.summaryZh,
                seed: pendingRemoval.title.length * 7 + 3,
              }
            : null
        }
        onCancel={() => setPendingRemoval(null)}
        onConfirm={() => {
          if (pendingRemoval) removeCard(pendingRemoval.id);
          setPendingRemoval(null);
        }}
      />
    </>
  );
}

function RecentDrawer({
  events,
  books,
  notes,
  onRemoveNote,
}: {
  events: StudyEvent[];
  books: ReaderBook[];
  notes: DrawerNote[];
  onRemoveNote: (noteId: string) => void;
}) {
  const sortedNotes = drawerNotesIn(notes, "notes").reverse();

  return (
    <>
      {/* C1：这一页改成看走势 —— 近两周的节奏、成色、最近读到的和可翻的记录
          都由 RecentLearningHub 画出来，原来那份「学了什么」的流水账撤下。 */}
      <RecentLearningHub events={events} notes={notes} books={books} />

      {sortedNotes.length ? (
        <section className="leafia-drawer-notes">
          <header>
            <span className="knowledge-eyebrow">Notes</span>
            <h4>便条 · 记录今天</h4>
          </header>
          <ul>
            {sortedNotes.map((note) => (
              <li key={note.id}>
                <span>
                  <strong>{note.title}</strong>
                  <small>{note.meta || "本机便条"}</small>
                </span>
                <button
                  type="button"
                  aria-label={`删除 ${note.title}`}
                  onClick={() => onRemoveNote(note.id)}
                >
                  <Trash2 size={13} />
                </button>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
    </>
  );
}


export function LeafiaDrawerPanel({
  drawerId,
  studyLog,
  books,
  drawerNotes,
  onRemoveNote,
  onClose,
}: {
  drawerId: DrawerId;
  studyLog: StudyEvent[];
  books: ReaderBook[];
  drawerNotes: DrawerNote[];
  onRemoveNote: (noteId: string) => void;
  onClose: () => void;
}) {
  const reducedMotion = useReducedMotion();
  const copy = DRAWER_COPY[drawerId];

  return (
    <AnimatePresence>
      <>
        <motion.aside
          className="study-shelf__drawer-panel leafia-functional-drawer"
          aria-label={`${copy.zhLabel}抽屉`}
          initial={{ opacity: 0, y: 72, scale: 0.96 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 48, scale: 0.98 }}
          transition={{
            duration: reducedMotion ? 0.01 : 0.4,
            ease: [0.22, 1, 0.36, 1],
          }}
        >
          {/* 抽屉拉开之后不是一张卡片，而是一页「网页」：标签页、地址栏，
              关闭是页面右上角那颗 ✕ —— 和单词本、练习册那两扇窗同一副样子。 */}
          <BrowserFrame
            label={copy.zhLabel}
            url={copy.url}
            onClose={onClose}
          >
            <div className="leafia-functional-drawer__body">
              {/* 页头只写标题：关闭是右上角那一颗 ✕ 的活，这儿不再摆第二只。 */}
              <header className="leafia-functional-drawer__head">
                <span>
                  <small>{copy.label}</small>
                  <strong>{copy.zhLabel}</strong>
                  <em>{copy.description}</em>
                </span>
              </header>
              {drawerId === "collection" ? (
                <WordDrawer />
              ) : drawerId === "materials" ? (
                <KnowledgeDrawer />
              ) : (
                <RecentDrawer
                  events={studyLog}
                  books={books}
                  notes={drawerNotes}
                  onRemoveNote={onRemoveNote}
                />
              )}
            </div>
          </BrowserFrame>
        </motion.aside>
      </>
    </AnimatePresence>
  );
}
